package spikecodegen

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"go/format"
	"go/token"
	"os"
	"os/exec"
	"path/filepath"

	"example.com/codegenbootstrapfixture/schema"
)

const generatorVersion = "codegenbootstrap-spike-v1"

// Generate renders a single generated file, validates it against the target
// package through a Go overlay, and only then replaces the last-good output.
// It is fixture code, not a proposed public API.
func Generate(models []schema.Model, outputPath, targetPackage string) error {
	if err := validate(models); err != nil {
		return fmt.Errorf("validate schema: %w", err)
	}

	generated, err := render(models)
	if err != nil {
		return err
	}

	absoluteOutput, err := filepath.Abs(outputPath)
	if err != nil {
		return fmt.Errorf("resolve output path: %w", err)
	}
	if _, err := os.Stat(absoluteOutput); err != nil {
		return fmt.Errorf("stat last-good output: %w", err)
	}

	candidate, err := os.CreateTemp(filepath.Dir(absoluteOutput), ".godj-candidate-*.go")
	if err != nil {
		return fmt.Errorf("create candidate output: %w", err)
	}
	candidatePath := candidate.Name()
	defer os.Remove(candidatePath)
	if err := candidate.Chmod(0o644); err != nil {
		candidate.Close()
		return fmt.Errorf("set candidate permissions: %w", err)
	}
	if _, err := candidate.Write(generated); err != nil {
		candidate.Close()
		return fmt.Errorf("write candidate output: %w", err)
	}
	if err := candidate.Sync(); err != nil {
		candidate.Close()
		return fmt.Errorf("sync candidate output: %w", err)
	}
	if err := candidate.Close(); err != nil {
		return fmt.Errorf("close candidate output: %w", err)
	}

	if err := validateCandidate(absoluteOutput, candidatePath, targetPackage); err != nil {
		return err
	}
	if err := os.Rename(candidatePath, absoluteOutput); err != nil {
		return fmt.Errorf("replace generated output: %w", err)
	}
	return nil
}

func validate(models []schema.Model) error {
	modelNames := make(map[string]struct{}, len(models))
	for _, model := range models {
		if !token.IsIdentifier(model.Name) {
			return fmt.Errorf("model name is not a Go identifier: %q", model.Name)
		}
		if _, duplicate := modelNames[model.Name]; duplicate {
			return fmt.Errorf("duplicate model name: %q", model.Name)
		}
		modelNames[model.Name] = struct{}{}

		fieldNames := make(map[string]struct{}, len(model.Fields))
		for _, field := range model.Fields {
			if !token.IsIdentifier(field.Name) {
				return fmt.Errorf("field name is not a Go identifier: %s.%q", model.Name, field.Name)
			}
			if field.GoType == "" {
				return fmt.Errorf("field Go type is empty: %s.%s", model.Name, field.Name)
			}
			if _, duplicate := fieldNames[field.Name]; duplicate {
				return fmt.Errorf("duplicate field name: %s.%s", model.Name, field.Name)
			}
			fieldNames[field.Name] = struct{}{}
		}
	}
	return nil
}

func render(models []schema.Model) ([]byte, error) {
	canonical, err := json.Marshal(models)
	if err != nil {
		return nil, fmt.Errorf("serialize schema for hash: %w", err)
	}
	hash := sha256.Sum256(canonical)

	var source bytes.Buffer
	fmt.Fprintln(&source, "// Code generated by the GoDj codegen bootstrap fixture. DO NOT EDIT.")
	fmt.Fprintf(&source, "// Generator: %s\n", generatorVersion)
	fmt.Fprintf(&source, "// Schema hash: %s\n\n", hex.EncodeToString(hash[:]))
	fmt.Fprintln(&source, "package models")
	for _, model := range models {
		fmt.Fprintf(&source, "\ntype %s struct {\n", model.Name)
		for _, field := range model.Fields {
			fmt.Fprintf(&source, "\t%s %s\n", field.Name, field.GoType)
		}
		fmt.Fprintln(&source, "}")
	}

	formatted, err := format.Source(source.Bytes())
	if err != nil {
		return nil, fmt.Errorf("format generated output: %w", err)
	}
	return formatted, nil
}

func validateCandidate(outputPath, candidatePath, targetPackage string) error {
	overlay, err := os.CreateTemp("", "godj-codegen-overlay-*.json")
	if err != nil {
		return fmt.Errorf("create overlay: %w", err)
	}
	overlayPath := overlay.Name()
	defer os.Remove(overlayPath)

	mapping := struct {
		Replace map[string]string
	}{
		Replace: map[string]string{outputPath: candidatePath},
	}
	if err := json.NewEncoder(overlay).Encode(mapping); err != nil {
		overlay.Close()
		return fmt.Errorf("encode overlay: %w", err)
	}
	if err := overlay.Close(); err != nil {
		return fmt.Errorf("close overlay: %w", err)
	}

	buildDirectory, err := os.MkdirTemp("", "godj-codegen-build-*")
	if err != nil {
		return fmt.Errorf("create candidate build directory: %w", err)
	}
	defer os.RemoveAll(buildDirectory)

	// Compile the package and its test files without executing user tests or
	// package initialization as part of generation.
	command := exec.Command(
		"go", "test", "-c",
		"-overlay", overlayPath,
		"-o", filepath.Join(buildDirectory, "candidate.test"),
		targetPackage,
	)
	output, err := command.CombinedOutput()
	if err != nil {
		return fmt.Errorf("candidate package validation failed: %w\n%s", err, output)
	}
	return nil
}
